package com.angle.trading.security;import jakarta.servlet.http.*;import org.slf4j.Logger;import org.slf4j.LoggerFactory;import org.springframework.security.core.AuthenticationException;import org.springframework.security.web.AuthenticationEntryPoint;import org.springframework.stereotype.Component;import java.io.IOException;@Componentpublic class CustomAuthenticationEntryPoint        implements AuthenticationEntryPoint {    private static final Logger log =            LoggerFactory.getLogger(CustomAuthenticationEntryPoint.class);    @Override    public void commence(HttpServletRequest request,                         HttpServletResponse response,                         AuthenticationException authException)            throws IOException {        log.info("Authentication Required");        response.sendRedirect("/auth/login");    }}